const mc_block_loot_entry_t *mc_block_loot_entry_from_state(int state_id) {
    if (state_id < 0) return NULL;
    if ((size_t)state_id >= GLOBAL_BLOCK_STATES_COUNT) return NULL;
    uint16_t block_index = GLOBAL_BLOCK_STATES[state_id].block_index;
    if ((size_t)block_index >= MC_BLOCK_LOOT_TABLE_SIZE) return NULL;
    return &mc_block_loot_table[block_index];
}

int mc_block_loot_default_item_id_from_state(int state_id, int fallback) {
    const mc_block_loot_entry_t *entry = mc_block_loot_entry_from_state(state_id);
    if (!entry) return fallback;
    if ((entry->flags & MC_BLOCK_LOOT_FLAG_SUPPORTED) == 0u) return fallback;
    if (entry->item_id < 0 || entry->count == 0u) return fallback;
    return entry->item_id;
}
